SELECT 
FROM task t
LEFT JOIN store st ON t.store_id = st.id

    AND t.store_id = #{query.storeId}
    AND t.source_type = #{query.sourceType}
    AND t.status = #{query.status}

ORDER BY t.id DESC
LIMIT #{page.offset}, #{page.size}

SELECT COUNT(*)
FROM task t

    AND t.store_id = #{query.storeId}
    AND t.source_type = #{query.sourceType}
    AND t.status = #{query.status}
